<script setup lang="ts">
import {computed,ref,watch,useId,nextTick,useAttrs} from 'vue';import {notify,extraMessage} from '../lib/messages';
defineOptions({inheritAttrs:false});
const props=defineProps<{modelValue:string|null;options:{value:string|null;label:string;code?:string;disabled?:boolean}[];label:string;placeholder?:string;disabled?:boolean;required?:boolean}>();
const emit=defineEmits<{'update:modelValue':[value:string|null]}>(),attrs=useAttrs(),input=ref<HTMLInputElement>(),open=ref(false),query=ref(''),search=ref(''),active=ref(-1),listId=useId();
const normalize=(value:string)=>value.trim().normalize('NFKC').toLocaleLowerCase();
const code=(option:typeof props.options[number])=>option.code??String(props.options.filter(o=>o.value!==null).indexOf(option)+1).padStart(2,'0');
const selected=computed(()=>props.options.find(o=>o.value===props.modelValue)),options=computed(()=>props.options.filter(o=>o.value!==null&&normalize(code(o)+' '+o.label).includes(normalize(search.value))));
const selection=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)});
const exact=()=>props.options.filter(o=>o.value!==null&&!o.disabled&&(normalize(o.label)===normalize(query.value)||normalize(code(o))===normalize(query.value)));
function blocked(){return props.disabled||input.value?.matches(':disabled');}
function validity(silent=false){const matches=!!(selected.value&&query.value===selected.value.label||!query.value&&!props.modelValue);input.value?.setCustomValidity(matches?'':'请从候选项中选择'+props.label);if(matches&&extraMessage.value?.source===input.value)extraMessage.value=null;if(!silent)input.value?.dispatchEvent(new CustomEvent('field-validated',{bubbles:true}));return matches;}
watch([()=>props.modelValue,()=>JSON.stringify(props.options)],()=>{query.value=selected.value?.label??'';if(props.modelValue===null)query.value='';void nextTick(()=>validity());},{immediate:true});
function choose(value:string|null,close=true,silent=false){const option=props.options.find(o=>o.value===value);if(!option||option.disabled||blocked())return false;const text=value===null?'':option.label,changed=value!==props.modelValue||query.value!==text;if(value!==props.modelValue)emit('update:modelValue',value);query.value=text;if(close)open.value=false;active.value=-1;input.value?.setCustomValidity('');if(extraMessage.value?.source===input.value)extraMessage.value=null;if(changed&&!silent)void nextTick(()=>validity());return true;}
function commit(report=false,silent=false){if(blocked())return false;const found=exact();if(found.length===1)return choose(found[0]!.value,true,silent);if(!query.value&&props.options.some(o=>o.value===null))return choose(null,true,silent);const valid=validity(silent);if(report&&!valid&&input.value)notify('E',props.label+'未匹配候选项，请选择已有资料',input.value);return valid;}
function edit(event:Event){search.value=query.value;open.value=!!query.value;active.value=-1;if((event as InputEvent).isComposing)return;const found=exact();if(found.length===1)choose(found[0]!.value,false);else if(!query.value&&props.options.some(o=>o.value===null))choose(null,false);void nextTick(()=>validity());}
function showAll(){if(blocked())return;open.value=true;search.value='';active.value=-1;void nextTick(()=>input.value?.focus());}
function blur(){commit();open.value=false;}
function key(event:KeyboardEvent){if(event.isComposing||event.keyCode===229)return;if(event.key==='Escape'&&open.value){event.preventDefault();event.stopPropagation();query.value=props.modelValue===null?'':selected.value?.label??'';open.value=false;validity();}else if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(!open.value){open.value=true;search.value='';}const enabled=options.value.map((o,i)=>o.disabled?-1:i).filter(i=>i>=0),index=enabled.indexOf(active.value),direction=event.key==='ArrowDown'?1:-1;if(enabled.length){active.value=enabled[index<0?(direction>0?0:enabled.length-1):(index+direction+enabled.length)%enabled.length]!;void nextTick(()=>document.getElementById(listId+'-'+active.value)?.scrollIntoView({block:'nearest'}));}}else if(event.key==='Enter'){event.preventDefault();event.stopPropagation();if(open.value&&active.value>=0){choose(options.value[active.value]!.value);return;}if(exact().length===1){commit();return;}if(!open.value)search.value=query.value;const enabled=options.value.filter(o=>!o.disabled);if(query.value&&enabled.length===1){choose(enabled[0]!.value);return;}if(!query.value){commit(true);open.value=false;return;}open.value=true;if(!enabled.length)commit(true);}}
</script>
<template><div class="match-select" @value-help="showAll"><select v-model="selection" :disabled="disabled" hidden tabindex="-1" aria-hidden="true"><option v-for="o in props.options" :key="o.value??'_none'" :value="o.value" :data-code="o.code??String(props.options.filter(p=>p.value!==null).indexOf(o)+1).padStart(2,'0')" :disabled="o.disabled">{{ o.label }}</option></select><input ref="input" v-bind="attrs" v-model="query" type="text" role="combobox" :aria-label="label" :aria-expanded="open" aria-autocomplete="list" :aria-controls="listId" :aria-activedescendant="open&&active>=0?listId+'-'+active:undefined" :placeholder="placeholder??'输入文字匹配，或按 F4 选择'" :disabled="disabled" :required="required" autocomplete="off" enterkeyhint="done" @input="edit" @compositionend="edit" @field-commit="commit(false,true)" @blur="blur" @keydown="key"><div v-if="open&&!disabled" :id="listId" class="match-options" role="listbox" :aria-label="label+'候选项'"><div class="match-table-head" aria-hidden="true"><span>编号</span><span>{{ label }}</span></div><button v-for="(o,index) in options" :id="listId+'-'+index" :key="o.value!" type="button" role="option" :aria-selected="o.value===modelValue" :disabled="o.disabled" :class="{active:index===active}" @mousedown.prevent @click="choose(o.value)"><span class="match-code">{{ code(o) }}</span><span>{{ o.label }}</span></button><p v-if="!options.length">没有匹配的候选项</p></div></div></template>
<style scoped>
.match-select{position:relative}.match-select select[hidden]{display:none}.match-select input:focus{outline:2px solid #0868c9;outline-offset:-2px;border-color:#0868c9}.match-options{position:absolute;top:100%;left:0;right:0;z-index:25;max-height:280px;overflow:auto;background:var(--paper);border:1px solid #8a969f;border-radius:10px;box-shadow:0 3px 8px #29384629;padding:0}.match-table-head,.match-options button{display:grid;grid-template-columns:minmax(70px,.65fr) minmax(0,2fr);gap:18px;padding:10px 18px;align-items:center;text-align:left}.match-table-head{position:sticky;top:0;z-index:1;background:var(--paper);border-bottom:1px solid #dce0e3;font-weight:600;font-size:14px;color:#243745}.match-options button{width:100%;border:0;border-radius:0;background:transparent;white-space:normal;margin:0;font-size:14px;line-height:1.5;color:#516b82}.match-options button span{overflow-wrap:anywhere}.match-options button.active,.match-options button:hover{background:#e9f2fc}.match-options button[aria-selected=true]{font-weight:600}.match-options p{padding:12px 18px;margin:0;font-size:13px;color:var(--muted)}.match-code{font-variant-numeric:tabular-nums}@media(max-width:560px){.match-table-head,.match-options button{grid-template-columns:60px minmax(0,1fr);gap:12px;padding:10px 12px}}
</style>
